from rdkit import Chem
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
m=Chem.MolFromMolFile('ligand.mol',removeHs=False)
x=np.array(m.GetConformer().GetPositions())
fig,ax=plt.subplots(figsize=(8,8))
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
 ax.plot(x[[i,j],0],x[[i,j],1],'k-',lw=1.5)
for i in [0,4,7,20,23]:ax.plot([0,x[i,0]],[0,x[i,1]],'--',color='gray')
color={'C':'black','H':'silver','N':'blue','O':'red'}
for a in m.GetAtoms():
 i=a.GetIdx();s=a.GetSymbol()
 ax.scatter(*x[i,:2],c=color[s],s=25 if s=='H' else 90)
 if s!='H':ax.annotate(s+str(i),x[i,:2],xytext=(4,4),textcoords='offset points')
ax.scatter(0,0,c='purple',s=160);ax.text(.1,.1,'Mo');ax.set_aspect('equal');fig.savefig('check.png')
print('max backbone z',max(abs(x[i,2]) for i in [0,1,2,4,5,6,7,14,15,16,17,18,20,21,22,23]))
print('min nonbond distances')
rows=open('answer.xyz').readlines()[2:]; els=[r.split()[0] for r in rows]; coords=np.array([[float(t) for t in r.split()[1:]] for r in rows])
for i in range(len(coords)):
 for j in range(i):
  d=np.linalg.norm(coords[i]-coords[j]);
  if d<.8: print(i,j,els[i],els[j],d)
